#include <bits/stdc++.h>
using namespace std;

static int n, t;

struct Room {
    int i, j;
    array<bool, 61> infected;
    array<bool, 61> accessible;
    int scientists, capsules;

    Room() : scientists(0), capsules(0) {
        infected.fill(false);
        accessible.fill(true);
    }

    int get_node_id(int timestamp) const {
        return 2 + i + n * j + (n * n) * timestamp;
    }

    void set_reactor() {
        accessible.fill(false);
    }

    void set_infected(int timestamp = 0) {
        if (accessible[timestamp]) {
            accessible[timestamp] = false;
            infected[timestamp] = true;
        }
    }

    void spread_infection(int timestamp);
};

static array<array<Room, 10>, 10> floorplan;

void Room::spread_infection(int timestamp) {
    if (infected[timestamp]) {
        set_infected(timestamp + 1);
        if (i > 0) floorplan[i - 1][j].set_infected(timestamp + 1);
        if (i < n - 1) floorplan[i + 1][j].set_infected(timestamp + 1);
        if (j > 0) floorplan[i][j - 1].set_infected(timestamp + 1);
        if (j < n - 1) floorplan[i][j + 1].set_infected(timestamp + 1);
    }
}

struct EdmondsKarp {
    struct Edge {
        int to, rev;
        double cap;
    };

    vector<vector<Edge>> g;

    EdmondsKarp(int n) : g(n) {}

    void add_edge(int v, int to, double cap) {
        Edge a{to, (int)g[to].size(), cap};
        Edge b{v, (int)g[v].size(), 0.0};
        g[v].push_back(a);
        g[to].push_back(b);
    }

    double augment(int s, int t) {
        vector<double> cap(g.size(), 0.0);
        vector<pair<int, int>> parent(g.size(), {-1, -1});
        queue<int> q;

        cap[s] = INFINITY;
        q.push(s);

        while (!q.empty() && cap[t] == 0.0) {
            int v = q.front();
            q.pop();

            for (int i = 0; i < (int)g[v].size(); i++) {
                Edge &e = g[v][i];

                if (e.cap > 1e-12 && cap[e.to] == 0.0) {
                    cap[e.to] = min(cap[v], e.cap);
                    parent[e.to] = {v, i};
                    q.push(e.to);
                }
            }
        }

        if (cap[t] == 0.0) return 0.0;

        for (int v = t; v != s; v = parent[v].first) {
            int pv = parent[v].first;
            int pe = parent[v].second;
            Edge &e = g[pv][pe];

            e.cap -= cap[t];
            g[v][e.rev].cap += cap[t];
        }

        return cap[t];
    }

    double max_flow(int s, int t) {
        double total = 0.0;

        while (true) {
            double f = augment(s, t);
            if (f <= 1e-12) break;
            total += f;
        }

        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);

    cin >> n >> t;

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            floorplan[i][j].i = i;
            floorplan[i][j].j = j;

            if (line[j] == 'Y') floorplan[i][j].set_reactor();
            else if (line[j] == 'Z') floorplan[i][j].set_infected();
            else floorplan[i][j].scientists = line[j] - '0';
        }
    }

    for (int i = 0; i < n; i++) {
        string line;
        cin >> line;

        for (int j = 0; j < n; j++) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                floorplan[i][j].capsules = line[j] - '0';
            }
        }
    }

    for (int c = 0; c <= t; c++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (c < t) floorplan[i][j].spread_infection(c);
            }
        }
    }

    EdmondsKarp mf(n * n * (t + 1) + 2);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            const Room &room = floorplan[i][j];

            if (room.scientists > 0) {
                mf.add_edge(0, room.get_node_id(0), room.scientists);
            }

            if (room.capsules > 0) {
                mf.add_edge(room.get_node_id(t), 1, room.capsules);
            }

            for (int c = 0; c < t; c++) {
                if (room.capsules > 0) {
                    mf.add_edge(room.get_node_id(c), room.get_node_id(t), 1000);
                }

                if (room.accessible[c]) {
                    if (i > 0 && floorplan[i - 1][j].accessible[c]) {
                        mf.add_edge(room.get_node_id(c), floorplan[i - 1][j].get_node_id(c + 1), 1000);
                    }

                    if (i < n - 1 && floorplan[i + 1][j].accessible[c]) {
                        mf.add_edge(room.get_node_id(c), floorplan[i + 1][j].get_node_id(c + 1), 1000);
                    }

                    if (j > 0 && floorplan[i][j - 1].accessible[c]) {
                        mf.add_edge(room.get_node_id(c), floorplan[i][j - 1].get_node_id(c + 1), 1000);
                    }

                    if (j < n - 1 && floorplan[i][j + 1].accessible[c]) {
                        mf.add_edge(room.get_node_id(c), floorplan[i][j + 1].get_node_id(c + 1), 1000);
                    }
                }
            }
        }
    }

    cout << int(mf.max_flow(0, 1)) << '\n';

    return 0;
}
